(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.008+t*0.15)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.009-t*0.18)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*40, 0.13, 1.4]
  ];
  let aS=0, iS=0, aS2=0, iS2=0, aS3=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2 += Math.sin(d*f*2.2-t*sp*1.4+0.8);
    iS2 += Math.sin(d*f*1.6+t*sp*1.1+2.3);
    aS3 += Math.sin(d*f*4.5-t*sp*2.8+1.2)*Math.exp(-d*0.003);
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, act2 = aS2/n, inh2 = iS2/n, hi = aS3/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const cross1 = act*inh2*0.3, cross2 = act2*inh*0.2;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+cross1+cross2)*2.2);
  const detail = Math.tanh((act2-inh2*0.6+hi*0.4)*2.8)*0.35;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const edge = 1.0-Math.abs(reaction-detail)*0.5;
  const blend = reaction*0.55+detail*0.2+cell*0.15+spiral*0.1;
  const v = Math.max(0, Math.min(1, blend*0.5+0.5));
  const pal = [[5,10,45],[10,45,85],[12,90,115],[18,140,135],[60,175,140],[170,195,80],[220,165,55],[210,110,60],[185,60,70],[120,30,55],[50,15,40],[5,10,45]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15+detail*0.1;
  const glow = Math.max(0, reaction-0.5)*0.6;
  const eBoost = Math.abs(reaction-detail)>0.4?1.1:1.0;
  const final = lum*eBoost+glow;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f+glow*40)*final)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f+glow*25)*final)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f+glow*15)*final)|0
  ];
}
